# Real imported state demonstrates that softening never hides physical contact.
m=copy.deepcopy(base);m['time']=0;m['bodies']=[{'id':'a','name':'Inbound A','kind':'craft','mass':1e-9,'radius':.01,'display':3,'x':-1,'y':0,'vx':10,'vy':0,'color':'#8fe8c2'},{'id':'b','name':'Inbound B','kind':'craft','mass':1e-9,'radius':.01,'display':3,'x':1,'y':0,'vx':-10,'vy':0,'color':'#f4b37e'}];m['nodes']=[];m['selectedId']='a';m['frame']='inertial';m['camera']={'x':0,'y':0,'scale':100};m['config'].update(G=.0001,dt=5,softening=20,tolerance=.25,collision='halt',horizon=10);m.pop('baseline',None);m.pop('expectedEnergy',None);m['events']=[];loadfixture(savefixture('head-on-collision-mission.json',m),'window.orbitLab.getState().selectedId==="a"');click('Play simulation');ab('wait','--fn','window.orbitLab.getState().events.some(e=>e.type==="Contact")');col=data();check('actual high-softening head-on collision halts near contact',col['paused'] and .095<col['time']<.105,col['time']);check('collision produces exactly one contact event',len([e for e in col['events'] if e['type']=='Contact'])==1);screenshot('22-contact-halt.png')
